import React, { useMemo, useRef, useState } from "react";
import { AlertCircle, Archive, Camera, Check, ChevronRight, ClipboardCheck, Clock3, Download, FileBarChart, HardHat, Headphones, MapPin, Maximize, Play, Plus, Radio, RefreshCw, Search, Send, Settings2, ShieldCheck, Sparkles, Target, Wifi } from "lucide-react";
import { sceneImages, sceneVideos } from "../data/demoSceneMedia";
import { Button, IconButton, Pill, toneFor, PageHeader, SectionCard, MetricCard, Field, Toolbar, Modal, Drawer, downloadText, cx } from "./PrototypeUI";
import { tasks as taskSeed, helmetInventory, projectNames } from "./PrototypeFixtures";
import "./theme-prototype-retake.css";
import "./prototype-task-helmet.css";

type PageProps = { notify: (message: string) => void; navigate?: (path: string, focusId?: string) => void };
export type Task = { id: string; name: string; type: string; project: string; inspector: string; date: string; time: string; status: string; priority: string; device: string; template: string; description: string; checks: string[] };
const taskTypes = ["用电安全检查", "消防安全检查", "复查验收", "动火临电", "综合安全检查"];
const taskChecks = ["配电箱闭锁", "线缆绝缘", "漏电保护", "消防通道", "警示标识", "现场取证"];
const taskTemplates = ["用电安全检查模板 V2.3", "消防设施检查模板 V1.9", "隐患复查模板 V1.6", "动火临电检查模板 V1.2", "综合安全检查模板 V1.0"];
const tasksStorage = "safety-prototype-tasks-v1";
const activeTaskStorage = "safety-prototype-active-task-v1";
function storeValue(key: string, value: unknown) { try { sessionStorage.setItem(key, JSON.stringify(value)); } catch { /* The current page remains usable when storage is unavailable. */ } }
function readValue<T>(key: string, fallback: T): T { try { const stored = sessionStorage.getItem(key); return stored ? JSON.parse(stored) as T : fallback; } catch { return fallback; } }
function useDemoState<T>(key: string, seed: T) {
  const [state, setState] = useState(() => ({ key, value: readValue(key, seed) }));
  const latest = useRef(state);
  if (latest.current.key !== key) {
    const next = { key, value: readValue(key, seed) };
    latest.current = next;
    setState(next);
  }
  const setStoredValue: React.Dispatch<React.SetStateAction<T>> = update => {
    const current = latest.current.key === key ? latest.current.value : readValue(key, seed);
    const value = typeof update === "function" ? (update as (current: T) => T)(current) : update;
    latest.current = { key, value };
    storeValue(key, value);
    setState(latest.current);
  };
  return [latest.current.value, setStoredValue] as const;
}
const availableHelmet = (project: string) => helmetInventory.find(helmet => helmet.project === project && helmet.status !== "离线");
const taskHelmetName = (task: Task) => (helmetInventory.find(helmet => helmet.name === task.device && helmet.project === task.project) || availableHelmet(task.project) || helmetInventory.find(helmet => helmet.project === task.project))?.name || helmetInventory[0].name;
function goTo(navigate: PageProps["navigate"], path: string, focusId?: string) { if (navigate) navigate(path, focusId); else window.location.assign(`/theme-prototype.html?page=${encodeURIComponent(path)}${focusId ? `&focus=${encodeURIComponent(focusId)}` : ""}`); }
const nowText = () => new Date().toLocaleString("sv-SE");
const nowTime = () => new Date().toLocaleTimeString("zh-CN", { hour12: false });
const csvText = (rows: string[][]) => `\uFEFF${rows.map(row => row.map(cell => `"${cell.replace(/"/g, '""')}"`).join(",")).join("\n")}`;
const seededTasks: Task[] = taskSeed.map(row => ({ id: row[0], name: row[1], type: row[2], project: row[3], inspector: row[4], date: row[5].split(" ")[0], time: row[5].split(" ")[1], status: row[6], priority: row[7], device: row[8], template: taskTemplates[Math.max(0, taskTypes.indexOf(row[2]))], description: "按检查模板核查现场消防与用电安全情况，补充照片、检查记录并归档证据。", checks: taskChecks.slice(0, 2) }));
export function readPrototypeTasks(): Task[] { return readValue(tasksStorage, seededTasks); }
const newTask = (): Task => ({ id: "", name: "齐鲁科技园配电室专项检查", type: "用电安全检查", project: "齐鲁科技园", inspector: "张三", date: new Date().toLocaleDateString("sv-SE"), time: "09:30", status: "待派发", priority: "中", device: "aa的智能安全帽", template: taskTemplates[0], description: "核查配电室配电箱闭锁、线缆绝缘、警示标识和消防通道情况。", checks: [] });

export function TasksPage({ notify, navigate }: PageProps) {
  const [rows, setRows] = useDemoState(tasksStorage, seededTasks);
  const [query, setQuery] = useState("");
  const [statusFilter, setStatusFilter] = useState("全部状态");
  const [typeFilter, setTypeFilter] = useState("全部类型");
  const [projectFilter, setProjectFilter] = useState("全部项目");
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [modal, setModal] = useState<"new" | "bind" | "dispatch" | null>(null);
  const [bindReturn, setBindReturn] = useState<"new" | "detail" | "dispatch">("detail");
  const [bindingProject, setBindingProject] = useState("全部项目");
  const [selectedHelmet, setSelectedHelmet] = useState(helmetInventory[0].name);
  const [draft, setDraft] = useState<Task>(newTask);
  const [error, setError] = useState("");
  const selected = rows.find(row => row.id === selectedId) ?? null;
  const filtered = useMemo(() => rows.filter(row => (!query.trim() || [row.id, row.name, row.project, row.inspector, row.device].join(" ").includes(query.trim())) && (statusFilter === "全部状态" || row.status === statusFilter) && (typeFilter === "全部类型" || row.type === typeFilter) && (projectFilter === "全部项目" || row.project === projectFilter)), [rows, query, statusFilter, typeFilter, projectFilter]);
  const patchTask = (id: string, patch: Partial<Task>) => setRows(items => items.map(row => row.id === id ? { ...row, ...patch } : row));
  const changeDraft = (key: keyof Task, value: string) => setDraft(current => key === "project" ? { ...current, project: value, device: availableHelmet(value)?.name || "未绑定" } : { ...current, [key]: value });
  const bindingTaskProject = bindReturn === "new" ? draft.project : selected?.project;
  const openBinding = (target: typeof bindReturn) => { const task = target === "new" ? draft : selected; setBindReturn(target); setSelectedHelmet(task ? taskHelmetName(task) : "未绑定"); setBindingProject(task?.project || "全部项目"); setError(""); setModal("bind"); };
  const closeBinding = () => setModal(bindReturn === "new" ? "new" : bindReturn === "dispatch" ? "dispatch" : null);
  const saveBinding = () => {
    if (!helmetInventory.some(helmet => helmet.name === selectedHelmet && helmet.status !== "离线" && helmet.project === bindingTaskProject)) { setError("请选择与任务所属项目一致的在线安全帽。"); return; }
    if (bindReturn === "new") changeDraft("device", selectedHelmet); else if (selected) patchTask(selected.id, { device: selectedHelmet });
    setError(""); closeBinding(); notify(`${selectedHelmet} 已绑定到${bindReturn === "new" ? "新建任务" : "当前任务"}`);
  };
  const saveTask = () => {
    if (!draft.name.trim() || !draft.date || !draft.time || !draft.description.trim()) { setError("请填写任务名称、检查日期、时间和任务说明。"); return; }
    if (draft.device !== "未绑定" && !helmetInventory.some(helmet => helmet.name === draft.device && helmet.project === draft.project && helmet.status !== "离线")) { setError("绑定安全帽与任务项目不一致或已离线，请重新绑定。"); return; }
    const next = { ...draft, name: draft.name.trim(), id: `RW${Date.now()}` };
    setRows(items => [next, ...items]); setSelectedId(next.id); setQuery(""); setStatusFilter("全部状态"); setTypeFilter("全部类型"); setProjectFilter("全部项目"); setModal(null); notify("检查任务已创建并进入待派发队列");
  };
  const dispatch = () => {
    if (!selected) return;
    if (!helmetInventory.some(helmet => helmet.name === selected.device && helmet.status !== "离线" && helmet.project === selected.project)) { setError("请先绑定与任务所属项目一致的在线安全帽。"); return; }
    const next = { ...selected, status: "待执行" };
    patchTask(selected.id, next); storeValue(activeTaskStorage, next); setModal(null); setError(""); notify("任务已派发至智能安全帽（本地演示）");
  };
  const exportTasks = () => { downloadText("检查任务清单.csv", csvText([["任务编号", "任务名称", "检查类型", "所属项目", "检查人员", "计划时间", "绑定安全帽", "状态", "优先级", "检查模板", "任务说明"], ...filtered.map(row => [row.id, row.name, row.type, row.project, row.inspector, `${row.date} ${row.time}`, row.device, row.status, row.priority, row.template, row.description])]), "text/csv;charset=utf-8"); notify(`已导出 ${filtered.length} 条检查任务`); };
  return <div className="page-stack prototype-task-page"><PageHeader eyebrow="WORKSPACE / 02" title="检查任务" description="从任务创建、设备绑定、派发执行到复查验收，统一管理检查节奏。" actions={<><Button icon={Download} variant="secondary" onClick={exportTasks}>导出清单</Button><Button icon={Plus} onClick={() => { setDraft(newTask()); setError(""); setModal("new"); }}>创建检查任务</Button></>} />
    <Toolbar><label className="search-field"><Search size={16} /><input value={query} onChange={event => setQuery(event.target.value)} placeholder="搜索任务编号、项目或检查人" /></label><select aria-label="任务状态" value={statusFilter} onChange={event => setStatusFilter(event.target.value)}>{["全部状态", "待派发", "待执行", "执行中", "待复查", "已完成"].map(item => <option key={item}>{item}</option>)}</select><select aria-label="检查类型" value={typeFilter} onChange={event => setTypeFilter(event.target.value)}>{["全部类型", ...taskTypes].map(item => <option key={item}>{item}</option>)}</select><select aria-label="所属项目" value={projectFilter} onChange={event => setProjectFilter(event.target.value)}>{projectNames.map(item => <option key={item}>{item}</option>)}</select><Button variant="secondary" icon={RefreshCw} onClick={() => { setQuery(""); setStatusFilter("全部状态"); setTypeFilter("全部类型"); setProjectFilter("全部项目"); }}>重置</Button></Toolbar>
    <div className="metric-grid compact"><MetricCard label="任务总数" value={String(rows.length)} detail={`${rows.filter(row => row.status === "已完成").length} 项完成`} icon={ClipboardCheck} tone="blue" /><MetricCard label="待派发" value={String(rows.filter(row => row.status === "待派发").length)} detail="需确认检查人与设备" icon={Send} tone="amber" /><MetricCard label="安全帽绑定" value={`${rows.filter(row => row.device !== "未绑定").length} / ${rows.length}`} detail={`${rows.filter(row => row.device === "未绑定").length} 项待绑定`} icon={HardHat} tone="green" /><MetricCard label="待复查" value={String(rows.filter(row => row.status === "待复查").length)} detail="现场证据与复查验收" icon={Clock3} tone="red" /></div>
    <SectionCard title="任务清单" eyebrow="TASK QUEUE" action={<span className="table-count">共 {filtered.length} 条 · 本地演示数据</span>}><div className="table-wrap"><table className="data-table prototype-task-table"><colgroup>{[260, 135, 125, 80, 145, 145, 95, 78].map((width, index) => <col key={index} style={{ width }} />)}</colgroup><thead><tr>{["任务", "项目", "类型", "检查人", "计划时间", "绑定安全帽", "状态", "操作"].map(head => <th key={head}>{head}</th>)}</tr></thead><tbody>{filtered.map(row => <tr key={row.id}><td><span title={row.name}>{row.name}</span><small>{row.id}</small></td><td title={row.project}>{row.project}</td><td>{row.type}</td><td>{row.inspector}</td><td>{row.date}<small>{row.time}</small></td><td title={row.device}>{row.device}</td><td><Pill tone={toneFor(row.status)}>{row.status}</Pill></td><td><Button variant="ghost" onClick={() => setSelectedId(row.id)}>查看</Button></td></tr>)}{!filtered.length && <tr><td colSpan={8} className="prototype-empty">暂无匹配任务，请调整或重置筛选条件。</td></tr>}</tbody></table></div></SectionCard>
    <Drawer title={selected?.name || "任务详情"} open={Boolean(selected) && !modal} onClose={() => setSelectedId(null)}>{selected && <div className="detail-stack"><div className="detail-status-row"><Pill tone={toneFor(selected.status)}>{selected.status}</Pill><span>检查完成度 {Math.round(selected.checks.length / taskChecks.length * 100)}%</span></div><div className="detail-grid">{[["任务编号", selected.id], ["检查类型", selected.type], ["所属项目", selected.project], ["检查人员", selected.inspector], ["计划时间", `${selected.date} ${selected.time}`], ["绑定安全帽", selected.device], ["检查模板", selected.template], ["优先级", selected.priority], ["任务说明", selected.description]].map(([label, value]) => <React.Fragment key={label}><span>{label}</span><strong>{value}</strong></React.Fragment>)}</div><SectionCard title="执行清单" eyebrow="FIELD CHECKLIST"><div className="task-checklist">{taskChecks.map(item => <label key={item}><input type="checkbox" checked={selected.checks.includes(item)} onChange={event => patchTask(selected.id, { checks: event.target.checked ? [...selected.checks, item] : selected.checks.filter(value => value !== item) })} />{item}<small>{selected.checks.includes(item) ? "已完成" : "待检查"}</small></label>)}</div></SectionCard><div className="detail-actions-stack">{selected.status === "待派发" && <Button icon={Send} onClick={() => { setError(""); setModal("dispatch"); }}>派发任务</Button>}{["待派发", "待执行"].includes(selected.status) && <Button variant="secondary" icon={HardHat} onClick={() => openBinding("detail")}>绑定/更换安全帽</Button>}<Button variant="secondary" icon={Play} onClick={() => { storeValue(activeTaskStorage, selected); goTo(navigate, "/helmet-live", selected.id); }}>进入现场执行</Button><Button variant="ghost" icon={FileBarChart} onClick={() => { storeValue(activeTaskStorage, selected); goTo(navigate, "/reports", selected.id); }}>生成检查报告</Button></div></div>}</Drawer>
    <Modal title="创建检查任务" open={modal === "new"} onClose={() => setModal(null)} wide><div className="form-grid"><Field label="任务名称" wide><input value={draft.name} onChange={event => changeDraft("name", event.target.value)} /></Field><Field label="检查类型"><select value={draft.type} onChange={event => { changeDraft("type", event.target.value); changeDraft("template", taskTemplates[taskTypes.indexOf(event.target.value)]); }}>{taskTypes.map(item => <option key={item}>{item}</option>)}</select></Field><Field label="所属项目"><select value={draft.project} onChange={event => changeDraft("project", event.target.value)}>{projectNames.slice(1).map(item => <option key={item}>{item}</option>)}</select></Field><Field label="检查日期"><input type="date" value={draft.date} onInput={event => changeDraft("date", event.currentTarget.value)} onChange={event => changeDraft("date", event.target.value)} /></Field><Field label="检查时间"><input type="time" value={draft.time} onInput={event => changeDraft("time", event.currentTarget.value)} onChange={event => changeDraft("time", event.target.value)} /></Field><Field label="检查人员"><select value={draft.inspector} onChange={event => changeDraft("inspector", event.target.value)}>{["张三", "李四", "王五", "赵六", "孙七"].map(item => <option key={item}>{item}</option>)}</select></Field><Field label="检查模板"><select value={draft.template} onChange={event => changeDraft("template", event.target.value)}>{taskTemplates.map(item => <option key={item}>{item}</option>)}</select></Field><Field label="优先级"><select value={draft.priority} onChange={event => changeDraft("priority", event.target.value)}>{["高", "中", "低"].map(item => <option key={item}>{item}</option>)}</select></Field><Field label="任务说明" wide><textarea value={draft.description} onChange={event => changeDraft("description", event.target.value)} /></Field></div><div className="binding-callout"><div><Pill tone="info">设备绑定</Pill><strong>{draft.device}</strong><span>派发后在现场端查看本地示例画面与证据。</span></div><Button variant="secondary" icon={HardHat} onClick={() => openBinding("new")}>绑定/更换安全帽</Button></div>{error && <p className="prototype-form-error" role="alert">{error}</p>}<div className="modal-foot"><Button variant="secondary" onClick={() => setModal(null)}>取消</Button><Button onClick={saveTask}>保存并创建</Button></div></Modal>
    <Modal title="绑定安全帽" open={modal === "bind"} onClose={closeBinding} wide><Toolbar><Field label="所属项目"><select value={bindingProject} onChange={event => setBindingProject(event.target.value)}>{projectNames.map(item => <option key={item}>{item}</option>)}</select></Field><span className="prototype-muted">只能绑定任务所属项目的在线设备。</span></Toolbar><div className="helmet-binding-grid">{helmetInventory.filter(helmet => bindingProject === "全部项目" || helmet.project === bindingProject).map(helmet => <button type="button" disabled={helmet.status === "离线" || helmet.project !== bindingTaskProject} key={helmet.id} className={cx("helmet-binding-card", selectedHelmet === helmet.name && "active")} onClick={() => { setSelectedHelmet(helmet.name); setError(""); }}><span className="binding-icon"><HardHat size={19} /></span><span><strong>{helmet.name}</strong><small>{helmet.id} · {helmet.model}</small><small>{helmet.project} · {helmet.wearer}</small></span><span className="binding-card-end"><Pill tone={toneFor(helmet.status)}>{helmet.status}</Pill><b>{helmet.battery}</b></span></button>)}</div><div className="binding-note"><ShieldCheck size={16} />已选择：{selectedHelmet}。绑定仅保存至当前浏览器演示记录。</div>{error && <p className="prototype-form-error" role="alert">{error}</p>}<div className="modal-foot"><Button variant="secondary" onClick={closeBinding}>取消</Button><Button onClick={saveBinding}>确认绑定</Button></div></Modal>
    <Modal title="派发检查任务" open={modal === "dispatch"} onClose={() => setModal(null)}>{selected && <><div className="detail-grid">{[["任务名称", selected.name], ["检查人员", selected.inspector], ["所属项目", selected.project], ["计划时间", `${selected.date} ${selected.time}`], ["绑定安全帽", selected.device], ["检查模板", selected.template]].map(([label, value]) => <React.Fragment key={label}><span>{label}</span><strong>{value}</strong></React.Fragment>)}</div><p className="prototype-note">确认后任务进入“待执行”，可在安全帽现场端查看关联任务与证据。本操作只更新本地演示状态。</p>{error && <p className="prototype-form-error" role="alert">{error}</p>}<div className="modal-foot"><Button variant="secondary" onClick={() => openBinding("dispatch")}>更换安全帽</Button><Button variant="secondary" onClick={() => setModal(null)}>取消</Button><Button onClick={dispatch}>确认派发</Button></div></>}</Modal>
  </div>;
}

function HelmetRetakePanel({ taskId, channel, frame, onFocus, onSave }: { taskId: string; channel: string; frame: string; onFocus: () => void; onSave: (image: string) => void }) {
  const [open, setOpen] = useState(false);
  const [refreshedAt, setRefreshedAt] = useState("");
  const [refreshCount, setRefreshCount] = useState(0);
  const [evidence, setEvidence] = useDemoState<{ image: string; channel: string; capturedAt: string } | null>(`safety-prototype-retake-v2-${taskId}-${channel}`, null);
  const [previewOnly, setPreviewOnly] = useState(false);
  const suggestion = "建议多角度拍摄内部接线及元器件状态，补充箱门锁闭和回路标识特写。";
  const startRetake = () => {
    onFocus();
    setPreviewOnly(false);
    setOpen(true);
  };
  const saveRetake = () => {
    setEvidence({ image: frame, channel, capturedAt: new Date().toLocaleTimeString("zh-CN", { hour12: false }) });
    onSave(frame);
    setOpen(false);
  };
  return <>
    <section className="demo-retake-panel" aria-label="建议补拍项">
      <header className="demo-retake-head">
        <h2><Camera size={17} />建议补拍项 <span>（{evidence ? 0 : 1}）</span></h2>
        <button type="button" className="demo-retake-refresh" onClick={() => {
          setRefreshedAt(new Date().toLocaleTimeString("zh-CN", { hour12: false }));
          setRefreshCount((count) => count + 1);
        }}><RefreshCw size={13} />刷新</button>
      </header>
      <article className="demo-retake-item">
        <div className="demo-retake-item-heading"><h3>配电箱内部线缆情况</h3><Pill tone={evidence ? "success" : "warning"}>{evidence ? "已补拍" : "待补拍"}</Pill></div>
        <p>{suggestion}</p>
        {evidence && <button type="button" className="demo-retake-evidence" onClick={() => { setPreviewOnly(true); setOpen(true); }}>
          <img src={evidence.image} alt="已保存的补拍截图" /><span>查看补拍记录<small>{evidence.capturedAt} · {evidence.channel}</small></span><ChevronRight size={15} />
        </button>}
        <div className="demo-retake-actions"><Button icon={Camera} variant={evidence ? "secondary" : "primary"} onClick={startRetake}>{evidence ? "重新补拍" : "去补拍"}</Button></div>
      </article>
      <p className="demo-retake-status" role="status">{refreshedAt ? `已刷新 ${refreshCount} 次 · ${refreshedAt} · ${evidence ? "暂无待补拍项" : "1 项待补拍"}` : "补充现场证据，便于后续复核"}</p>
    </section>
    <div className="demo-retake-dialog"><Modal title={previewOnly ? "补拍记录" : "补拍取证"} open={open} onClose={() => setOpen(false)} wide>
      <div className="demo-retake-capture">
        <figure><img src={previewOnly && evidence ? evidence.image : frame} alt="配电箱内部线缆补拍预览" /><figcaption>演示取证 · {previewOnly && evidence ? evidence.channel : channel}{previewOnly && evidence ? ` · ${evidence.capturedAt}` : " · 当前通道示例画面"}</figcaption></figure>
        <div><Pill tone={previewOnly ? "success" : "warning"}>{previewOnly ? "已保存补拍截图" : "补拍模式"}</Pill><h3>配电箱内部线缆情况</h3><p>{suggestion}</p><ul><li>内部接线及元器件状态</li><li>箱门锁闭状态</li><li>回路标识特写</li></ul><p className="demo-retake-note">{previewOnly ? "截图已关联本条补拍建议，可供复核查看。" : "保存后将在建议卡片中展示补拍记录，并更新待补拍数量。"}</p></div>
      </div>
      <div className="modal-foot"><Button variant="secondary" onClick={() => setOpen(false)}>{previewOnly ? "关闭" : "取消"}</Button>{!previewOnly && <Button icon={Camera} onClick={saveRetake}>保存补拍截图</Button>}</div>
    </Modal></div>
  </>;
}

type FieldClue = { key: string; title: string; time: string; risk: string; confidence: string; image: string; description: string; measure: string; checklist: string };
type FieldRecord = { id: string; key: string; title: string; risk: string; status: string; foundTime: string; image: string; source: string; project: string; checklist: string; description: string; measure: string; taskId?: string; taskName?: string; orderId?: string; assignee?: string; deadline?: string; orderCreatedAt?: string };
type FieldEvent = { id: string; time: string; title: string; status: string };
type MediaPreview = { title: string; src: string; type: "image" | "video"; note: string };
const fieldClues: FieldClue[] = [
  { key: "panel", title: "配电箱门未关闭", time: "15:04:12", risk: "高风险", confidence: "94%", image: sceneImages.electricalPanelOpen, description: "示例画面中配电箱门处于开启状态，建议现场核查箱门闭锁和内部防护。", measure: "核查配电箱门闭锁，关闭并上锁，补拍箱门与回路标识。", checklist: "配电箱门状态" },
  { key: "cable", title: "线缆防护待核查", time: "15:04:15", risk: "高风险", confidence: "89%", image: sceneImages.cableExposed, description: "线缆绝缘与连接防护情况待核查，建议补充内部接线及元器件近景。", measure: "由专业人员核查线缆绝缘、防护和连接状态，整改后补拍同角度照片。", checklist: "线缆连接情况" },
  { key: "corridor", title: "消防通道占用", time: "15:04:17", risk: "中风险", confidence: "90%", image: sceneImages.fireCorridorBlocked, description: "通道区域存在堆放物，建议核查疏散净宽和通行情况。", measure: "清理通道堆放物，保持疏散通道畅通并补充全景照片。", checklist: "消防通道" },
  { key: "extinguisher", title: "灭火器压力待核查", time: "15:04:18", risk: "中风险", confidence: "91%", image: sceneImages.extinguisherLowPressure, description: "灭火器压力表指针与有效期需现场核实，建议补拍压力表特写。", measure: "核查压力表和有效期，对失效器材进行更换并记录结果。", checklist: "灭火器检查" }
];
const fieldChecklist = [
  { title: "配电箱外观检查", state: "正常", key: "panel" }, { title: "配电箱门状态", state: "异常", key: "panel" }, { title: "线缆连接情况", state: "异常", key: "cable" },
  { title: "漏电保护器", state: "待检查", key: "panel" }, { title: "消防通道", state: "待检查", key: "corridor" }, { title: "现场照片取证", state: "待检查", key: "panel" },
  { title: "接地线连接检查", state: "正常", key: "cable" }, { title: "灭火器检查", state: "异常", key: "extinguisher" }, { title: "绝缘垫检查", state: "待检查", key: "panel" }
];
const fieldToTaskCheck: Record<string, string> = { "配电箱门状态": "配电箱闭锁", "线缆连接情况": "线缆绝缘", "漏电保护器": "漏电保护", "消防通道": "消防通道", "现场照片取证": "现场取证" };
const checklistForTask = (task: Task) => fieldChecklist.map(item => ({ ...item, state: task.checks.includes(fieldToTaskCheck[item.title]) ? (item.state === "异常" ? "异常" : "正常") : "待检查" }));
const defaultFieldRecords: FieldRecord[] = [
  ...fieldClues.filter(clue => clue.key !== "corridor").map((clue, index) => ({ id: `YH20250516001-00${index + 1}`, key: clue.key, title: clue.title, risk: clue.risk, status: clue.key === "extinguisher" ? "待复查" : "待派发", foundTime: `2025-05-16 ${clue.time}`, image: clue.image, source: "aa的智能安全帽", project: "齐鲁科技园", checklist: clue.checklist, description: clue.description, measure: clue.measure })),
  { id: "YH20250516001-004", key: "panel", title: "配电箱内灰尘较多", risk: "低风险", status: "待整改", foundTime: "2025-05-16 15:10:22", image: sceneImages.electricalPanelOpen, source: "aa的智能安全帽", project: "齐鲁科技园", checklist: "配电箱外观检查", description: "需现场核查配电箱内清洁与防尘状态。", measure: "按安全操作要求安排专业人员进行清洁与检查。" },
  { id: "YH20250516001-005", key: "cable", title: "接地线标识不清晰", risk: "低风险", status: "已整改", foundTime: "2025-05-16 15:12:45", image: sceneImages.cableExposed, source: "aa的智能安全帽", project: "齐鲁科技园", checklist: "接地线连接检查", description: "接地线标识已补充，待后续归档核验。", measure: "补充清晰、耐久的接地线标识并留存照片。" }
].map(row => ({ ...row, taskId: seededTasks[0].id, taskName: seededTasks[0].name }));
const initialEvents: FieldEvent[] = [{ id: "initial-4", time: "15:04", title: "AI 识别配电箱门未关闭", status: "建议核查" }, { id: "initial-3", time: "14:50", title: "补拍请求已记录", status: "处理中" }, { id: "initial-2", time: "14:40", title: "安全帽进入 B1 配电室", status: "已记录" }, { id: "initial-1", time: "14:30", title: "任务开始，设备完成签到", status: "已完成" }];
const riskTone = (risk: string) => risk === "中风险" ? "warning" : risk === "低风险" ? "success" : toneFor(risk);

export function HelmetPage({ notify, navigate, expert = false }: PageProps & { expert?: boolean }) {
  const [currentTask, setCurrentTask] = useState<Task>(() => readValue(activeTaskStorage, seededTasks[0]));
  const [channel, setChannel] = useState(() => { const task = readValue<Task>(activeTaskStorage, seededTasks[0]); return taskHelmetName(task); });
  const [project, setProject] = useState("全部项目");
  const [talking, setTalking] = useState(false);
  const [recording, setRecording] = useState(false);
  const [infrared, setInfrared] = useState(false);
  const [lightOn, setLightOn] = useState(false);
  const [hdMode, setHdMode] = useState(true);
  const [sosOpen, setSosOpen] = useState(false);
  const [settingsOpen, setSettingsOpen] = useState(false);
  const [reviewOpen, setReviewOpen] = useState(false);
  const [activeKey, setActiveKey] = useState("panel");
  const [activeChecklist, setActiveChecklist] = useState("配电箱门状态");
  const [checklist, setChecklist] = useDemoState(`safety-prototype-helmet-checklist-v2-${currentTask.id}`, checklistForTask(currentTask));
  const [records, setRecords] = useDemoState("safety-prototype-helmet-records-v1", defaultFieldRecords);
  const [events, setEvents] = useDemoState("safety-prototype-helmet-events-v1", initialEvents);
  const [clips, setClips] = useDemoState<{ id: string; title: string; createdAt: string; source: string; src: string }[]>("safety-prototype-helmet-clips-v1", []);
  const [preview, setPreview] = useState<MediaPreview | null>(null);
  const [selectedClue, setSelectedClue] = useState<FieldClue | null>(null);
  const [recordId, setRecordId] = useState<string | null>(null);
  const [orderMode, setOrderMode] = useState<"order" | "dispatch" | null>(null);
  const [orderForm, setOrderForm] = useState({ assignee: "李四", deadline: new Date().toLocaleDateString("sv-SE"), measure: "" });
  const [formError, setFormError] = useState("");
  const [reviewNote, setReviewNote] = useState("请补拍配电箱内部接线、箱门闭锁和回路标识特写，供远程专家复核。");
  const [reviewTarget, setReviewTarget] = useState("王工 · 电气专家");
  const [query, setQuery] = useState("");
  const [recordStatus, setRecordStatus] = useState("全部状态");
  const [refreshedAt, setRefreshedAt] = useState("");
  const [analysisAt, setAnalysisAt] = useState("");
  const [analysisOpen, setAnalysisOpen] = useState(false);
  const [syncAt, setSyncAt] = useState("");
  const currentHelmet = helmetInventory.find(item => item.name === channel) || helmetInventory[0];
  const activeClue = fieldClues.find(item => item.key === activeKey) || fieldClues[0];
  const frame = infrared ? sceneImages.infraredOverheat : activeClue.image;
  const activeRecord = records.find(record => record.id === recordId) || null;
  const visibleHelmets = helmetInventory.filter(item => project === "全部项目" || item.project === project);
  const filteredRecords = records.filter(record => (!query.trim() || `${record.id} ${record.title} ${record.source}`.includes(query.trim())) && (recordStatus === "全部状态" || record.status === recordStatus) && (project === "全部项目" || record.project === project));
  const completedChecks = checklist.filter(item => item.state !== "待检查").length;
  const addEvent = (title: string, status = "已记录") => setEvents(items => [{ id: `EVENT${Date.now()}-${items.length}`, time: nowTime(), title, status }, ...items].slice(0, 50));
  const switchChannel = (name: string) => { const helmet = helmetInventory.find(item => item.name === name); if (!helmet) return; setChannel(name); setActiveKey(name.includes("bb") ? "corridor" : "panel"); setInfrared(false); setTalking(false); setRecording(false); const task = currentTask.device === name && currentTask.project === helmet.project ? currentTask : readValue<Task[]>(tasksStorage, seededTasks).find(row => row.device === name && row.project === helmet.project); const nextTask = task || { ...seededTasks[0], id: `DEMO-${helmet.id}`, name: `${helmet.project}现场检查`, project: helmet.project, inspector: helmet.wearer, device: helmet.name, checks: [] }; setSyncAt(""); setCurrentTask(nextTask); storeValue(activeTaskStorage, nextTask); addEvent(`切换现场通道：${name}`); };
  const changeProject = (value: string) => { setProject(value); const available = helmetInventory.filter(item => value === "全部项目" || item.project === value); if (!available.some(item => item.name === channel) && available[0]) switchChannel(available[0].name); };
  const capture = (image = frame, title = `现场截图取证 ${records.filter(row => row.id.startsWith("SHOT")).length + 1}`) => { const next: FieldRecord = { id: `SHOT${Date.now()}`, key: activeKey, title, risk: activeClue.risk, status: "待派发", foundTime: nowText(), image, source: channel, project: currentTask.project, taskId: currentTask.id, taskName: currentTask.name, checklist: activeChecklist, description: `${title}，来源：${channel}；本地示例画面，建议人工复核。`, measure: activeClue.measure }; setRecords(items => [next, ...items]); addEvent(`${title}已加入现场记录`); notify("示例截图已加入现场隐患记录"); return next; };
  const toggleRecording = () => { if (recording) { const clip = { id: `CLIP${Date.now()}`, title: `${channel}现场录制演示片段`, createdAt: nowText(), source: channel, src: activeKey === "corridor" ? sceneVideos.fireCorridor : activeKey === "extinguisher" ? sceneVideos.extinguisherPressure : sceneVideos.helmetLive }; setClips(items => [clip, ...items]); addEvent("现场录制已停止，示例片段已保存"); setPreview({ title: clip.title, src: clip.src, type: "video", note: "本地图片轮播演示素材，不是实际现场录像。" }); } else addEvent(`开始现场录制演示：${channel}`, "录制中"); setRecording(value => !value); };
  const toggleTalk = () => { setTalking(value => !value); addEvent(talking ? "本地语音对讲演示已结束" : "本地语音对讲演示已开启", talking ? "已结束" : "对讲中"); };
  const downloadAsset = (src: string, filename: string) => { const link = document.createElement("a"); link.href = src; link.download = filename; document.body.appendChild(link); link.click(); link.remove(); };
  const exportRecords = () => { downloadText("现场隐患记录.csv", csvText([["隐患编号", "隐患描述", "风险等级", "当前状态", "发现时间", "来源设备", "所属项目", "整改单", "责任人", "整改期限"], ...filteredRecords.map(row => [row.id, row.title, row.risk, row.status, row.foundTime, row.source, row.project, row.orderId || "未生成", row.assignee || "待指派", row.deadline || "待设置"])]), "text/csv;charset=utf-8"); notify(`已导出 ${filteredRecords.length} 条现场隐患记录`); };
  const exportEvidence = () => { downloadText("安全帽现场证据包.json", JSON.stringify({ demo: true, task: currentTask, device: currentHelmet, records: filteredRecords, clips, events, checklist }, null, 2), "application/json;charset=utf-8"); notify("现场证据清单与处理记录已导出"); };
  const registerClue = (clue: FieldClue) => { const existing = records.find(row => row.key === clue.key && row.source === channel && row.title === clue.title && (row.taskId === currentTask.id || (!row.taskId && defaultFieldRecords.some(seed => seed.id === row.id && seed.taskId === currentTask.id)))); const row: FieldRecord = existing || { id: `YH${Date.now()}`, key: clue.key, title: clue.title, risk: clue.risk, status: "待派发", foundTime: nowText(), image: clue.image, source: channel, project: currentTask.project, taskId: currentTask.id, taskName: currentTask.name, checklist: clue.checklist, description: clue.description, measure: clue.measure }; if (!existing) setRecords(items => [row, ...items]); storeValue("safety-prototype-hazard-handoff-v1", { ...row, taskId: currentTask.id, taskName: currentTask.name, inspector: currentTask.inspector, checkType: /动火|临电|临时/.test(clue.title) ? "动火临电" : /消防|通道|灭火/.test(clue.title) ? "消防安全检查" : currentTask.type }); addEvent(`进入隐患登记：${clue.title}`); goTo(navigate, "/hazards", row.id); };
  const openOrder = (row: FieldRecord, mode: "order" | "dispatch") => { setRecordId(row.id); setOrderForm({ assignee: row.assignee || "李四", deadline: row.deadline || new Date().toLocaleDateString("sv-SE"), measure: row.measure }); setFormError(""); setOrderMode(mode); };
  const saveOrder = () => { if (!activeRecord || !orderMode) return; if (!orderForm.deadline || !orderForm.measure.trim()) { setFormError("请填写整改期限和整改措施。"); return; } const orderId = activeRecord.orderId || `ZG${Date.now()}`; const nextStatus = orderMode === "dispatch" ? (activeRecord.status === "待整改" ? "整改中" : "待整改") : activeRecord.status; setRecords(items => items.map(row => row.id === activeRecord.id ? { ...row, ...orderForm, measure: orderForm.measure.trim(), orderId, orderCreatedAt: row.orderCreatedAt || nowText(), status: nextStatus } : row)); addEvent(`${activeRecord.title}：${orderMode === "dispatch" ? `整改任务已指派给${orderForm.assignee}` : "整改单已生成"}`, nextStatus); notify(orderMode === "dispatch" ? "整改任务已写入本地记录" : "整改单已生成，可预览并导出"); setOrderMode(null); };
  const syncTask = () => {
    const taskRows = readValue<Task[]>(tasksStorage, seededTasks);
    const matchingTask = taskRows.find(row => row.id === currentTask.id && row.project === currentTask.project);
    if (!matchingTask) { notify("当前通道未关联已创建任务，请从任务清单进入现场后同步。"); return; }
    const mappedChecks = taskChecks.filter(item => item === "警示标识" ? matchingTask.checks.includes(item) : checklist.some(check => check.state !== "待检查" && fieldToTaskCheck[check.title] === item));
    const next = { ...matchingTask, checks: mappedChecks };
    storeValue(tasksStorage, taskRows.map(row => row.id === next.id ? next : row));
    storeValue(activeTaskStorage, next);
    setCurrentTask(next); setSyncAt(nowTime());
    addEvent(`已同步 ${mappedChecks.length} 项清单到任务 ${next.id}`);
    notify("现场清单已同步至当前任务记录");
  };
  const focusClue = (clue: FieldClue) => { setActiveKey(clue.key); setActiveChecklist(clue.checklist); setInfrared(false); };
  const focusChecklist = (title: string, key: string) => { setActiveChecklist(title); setActiveKey(key); setInfrared(false); };
  return <div className="page-stack prototype-helmet-page"><PageHeader eyebrow={expert ? "EXPERT DESK / 05" : "FIELD OPS / 03"} title={expert ? "远程专家" : "安全帽现场"} description="任务、设备、画面、清单、AI 线索和隐患取证集中在现场工作面 · 本地演示数据" actions={<><Button variant="secondary" icon={Download} onClick={exportEvidence}>导出证据包</Button><Button icon={Headphones} onClick={toggleTalk}>{talking ? "结束对讲" : "开始对讲"}</Button></>} />
    <Toolbar className="prototype-field-filter"><Field label="项目筛选"><select value={project} onChange={event => changeProject(event.target.value)}>{projectNames.map(item => <option key={item}>{item}</option>)}</select></Field><Field label="现场设备"><select value={channel} onChange={event => switchChannel(event.target.value)}>{visibleHelmets.map(item => <option key={item.id} value={item.name}>{item.name} · {item.status}</option>)}</select></Field><span className="prototype-muted">{currentHelmet.status === "离线" ? "离线设备仅显示最近示例素材" : "本地示例通道 · 不连接真实设备"}</span><Button variant="secondary" icon={Settings2} onClick={() => setSettingsOpen(true)}>现场设置</Button><Button variant="ghost" onClick={() => goTo(navigate, "/")}>退出现场</Button></Toolbar>
    <div className="helmet-context-strip"><div><span>当前任务</span><strong title={currentTask.name}>{currentTask.name}</strong><small>{currentTask.id} · {currentTask.project}</small></div><div><span>检查员</span><strong>{currentTask.inspector}</strong><small>{currentTask.status} · {Math.round(completedChecks / checklist.length * 100)}% 完成</small></div><div><span>回传状态</span><strong><i className="live-dot" />{currentHelmet.status === "离线" ? "离线素材预览" : "演示通道就绪"}</strong><small>示例延迟 280ms · {hdMode ? "1080P" : "720P"}</small></div><div><span>设备电量</span><strong>{currentHelmet.battery}</strong><small>{currentHelmet.network} · 最近回传 {currentHelmet.lastSeen}</small></div></div>
    <div className={cx("field-monitor-grid", expert && "expert-layout")}><aside className="channel-panel"><div className="channel-head"><div><div className="eyebrow">LIVE CHANNELS</div><h2>现场通道</h2></div><Pill tone="success">{visibleHelmets.filter(item => item.status !== "离线").length} 在线</Pill></div>{visibleHelmets.map(item => <button className={cx("channel-item", channel === item.name && "active")} type="button" key={item.name} onClick={() => switchChannel(item.name)}><span className="channel-avatar"><HardHat size={17} /></span><span><strong>{item.name}</strong><small>{item.project} · {item.wearer}</small></span><span className={cx("channel-state", item.status === "离线" && "offline")}><Wifi size={13} />{item.status}</span></button>)}{!visibleHelmets.length && <p>当前项目暂无现场通道。</p>}<div className="channel-footer"><Button variant="secondary" icon={RefreshCw} onClick={() => { setRefreshedAt(nowTime()); addEvent("现场通道列表已刷新"); }}>刷新通道</Button>{refreshedAt && <small className="prototype-channel-update" role="status">最近刷新 {refreshedAt}</small>}<div className="prototype-channel-task"><span>检查开始时间</span><strong>{currentTask.date} {currentTask.time}</strong><span>任务模板</span><strong>{currentTask.template}</strong></div></div></aside>
      <section className="stream-panel"><div className="stream-head"><div><Pill tone="info">DEMO</Pill><strong>{channel}</strong></div><div className="stream-head-actions"><Button variant="ghost" onClick={() => setHdMode(value => !value)}>{hdMode ? "1080P" : "720P"}</Button><IconButton label="放大当前画面" onClick={() => setPreview({ title: `${channel} · 当前画面`, src: frame, type: "image", note: "本地场景参考素材，不是真实视频回传。" })}><Maximize size={16} /></IconButton><IconButton label="保存当前画面" onClick={() => downloadAsset(frame, `${channel}-现场示例.jpg`)}><Download size={16} /></IconButton></div></div><div className={cx("stream-stage", infrared && "thermal-stage", lightOn && "prototype-light-on")}><img src={frame} alt={`${activeClue.title}场景参考`} /><div className="stream-grid-lines" /><div className="stream-hud-top"><Pill tone="danger">疑似线索 {fieldClues.length}</Pill><span>{infrared ? "红外测温演示" : activeChecklist}</span></div><div className="stream-center"><Radio size={34} /><strong>{recording ? "现场录制演示中" : "现场参考画面"}</strong><span>{talking ? "语音对讲演示已开启" : `${hdMode ? "高清" : "标准"}素材 · ${lightOn ? "补光灯已开启" : "点击截图保存证据"}`}</span></div><div className="stream-location"><MapPin size={14} />{currentHelmet.project} · 检查现场</div></div>
        <div className="prototype-model-summary"><div><span>当前识别引擎</span><strong>本地演示识别</strong><small>{analysisAt ? `${analysisAt} · ${fieldClues.length} 条示例线索，待人工核查` : "示例线索仅用于演示，可查看识别结果"}</small></div><Button variant="secondary" icon={Sparkles} onClick={() => { setAnalysisAt(nowTime()); setAnalysisOpen(true); addEvent("已生成本地演示识别结果", "建议核查"); }}>运行演示识别</Button></div>
        <div className="stream-toolbar"><button className={recording ? "active" : ""} onClick={toggleRecording}><Radio size={15} />{recording ? "停止录制" : "开始录制"}</button><button className={talking ? "active" : ""} onClick={toggleTalk}><Headphones size={15} />{talking ? "结束对讲" : "语音对讲"}</button><button className={infrared ? "active" : ""} onClick={() => setInfrared(value => !value)}><Target size={15} />红外测温</button><button className={lightOn ? "active" : ""} onClick={() => setLightOn(value => !value)}><Sparkles size={15} />补光灯</button><button onClick={() => capture()}><Archive size={15} />截图取证</button><button onClick={() => setPreview({ title: "历史关键帧", src: records.find(row => row.source === channel)?.image || frame, type: "image", note: `来源设备：${channel} · 本地保存的示例证据。` })}><Camera size={15} />历史帧</button><button className="sos" onClick={() => setSosOpen(true)}><AlertCircle size={15} />SOS</button></div><div className="stream-metrics"><div><span>回传延迟（示例）</span><strong>280ms</strong></div><div><span>电量</span><strong>{currentHelmet.battery}</strong></div><div><span>轨迹点</span><strong>36</strong></div><div><span>音频</span><strong>{talking ? "对讲演示中" : "待机"}</strong></div></div></section>
      <aside className="incident-panel"><div className="incident-head"><div><div className="eyebrow">AI CLUES</div><h2>疑似隐患</h2></div><Pill tone="danger">{fieldClues.length} 待确认</Pill></div>{fieldClues.map(clue => <button className={cx("incident-item", activeKey === clue.key && "active")} type="button" key={clue.key} onClick={() => { focusClue(clue); setSelectedClue(clue); }}><span className="incident-icon"><AlertCircle size={16} /></span><span><strong>{clue.title}</strong><small>{clue.time} · 置信度 {clue.confidence}</small></span><Pill tone={riskTone(clue.risk)}>{clue.risk}</Pill></button>)}<div className="incident-actions"><Button icon={Target} onClick={() => registerClue(activeClue)}>登记隐患</Button><Button variant="secondary" icon={Send} onClick={() => setReviewOpen(true)}>发送复核指令</Button></div><HelmetRetakePanel key={`${currentTask.id}-${channel}`} taskId={currentTask.id} channel={channel} frame={frame} onFocus={() => { focusChecklist("线缆连接情况", "cable"); }} onSave={image => { capture(image, "配电箱内部线缆补拍证据"); setChecklist(items => items.map(item => item.title === "现场照片取证" ? { ...item, state: "正常" } : item)); }} /></aside></div>
    <SectionCard title="巡检轨迹与时间线" eyebrow="INSPECTION TIMELINE" action={<span className="prototype-muted">已巡检：35 分钟 / 预计：60 分钟 · 演示</span>}><div className="prototype-patrol-timeline"><div className="prototype-patrol-bar">{[["正常", "14:30–14:45", "normal", 24], ["异常", "14:45–15:00", "abnormal", 23], ["当前", "15:00–15:05", "current", 8], ["待检查", "15:05–15:30", "pending", 45]].map(([label, range, state, width]) => <button key={label} className={String(state)} style={{ flex: Number(width) }} title={`${label} ${range}`} onClick={() => setPreview({ title: `${label}巡检轨迹 ${range}`, src: sceneVideos.locationReplay, type: "video", note: "本地轨迹图片轮播示例，供演示回放。" })}><span>{label}</span></button>)}</div><div className="prototype-time-labels"><span>14:30</span><span>14:45</span><span>15:00</span><span>15:15</span><span>15:30</span></div></div></SectionCard>
    <div className="helmet-lower-grid"><SectionCard title="设备与感知" eyebrow="DEVICE TELEMETRY"><div className="telemetry-grid">{[["安全帽编号", currentHelmet.id], ["设备型号", currentHelmet.model], ["网络状态", currentHelmet.network], ["GPS 定位", "北纬 31.2304° / 东经 121.4737°"], ["存储空间", "62GB / 100GB"], ["移动速度", "1.2 m/s"], ["设备温度", "32.6 °C"], ["运行时长", "02:45:18"], ["连接状态", currentHelmet.status === "离线" ? "离线" : "稳定"], ["跌倒检测", "未触发"], ["红外温度", "36.5 °C"], ["环境光照", lightOn ? "补光已开启" : "良好 320 lux"], ["烟雾检测", "未检测到"], ["AI 识别", `${fieldClues.length} 项示例线索`]].map(([label, value]) => <div key={label}><span>{label}</span><strong>{value}</strong></div>)}</div></SectionCard><SectionCard title="当前检查清单" eyebrow="FIELD CHECKLIST" action={<Button variant="ghost" onClick={syncTask}>同步任务</Button>}><div className="helmet-checklist">{checklist.map(item => <button type="button" className={cx(activeChecklist === item.title && "active")} key={item.title} onClick={() => focusChecklist(item.title, item.key)}><span className="check-index">{item.title === activeChecklist ? <Check size={14} /> : "·"}</span><strong>{item.title}</strong><Pill tone={item.state === "异常" ? "danger" : item.state === "正常" ? "success" : "warning"}>{item.state}</Pill></button>)}</div><div className="prototype-check-result"><span>当前项：{activeChecklist}</span><select aria-label="检查项结果" value={checklist.find(item => item.title === activeChecklist)?.state || "待检查"} onChange={event => { const state = event.target.value; setChecklist(items => items.map(item => item.title === activeChecklist ? { ...item, state } : item)); addEvent(`${activeChecklist}：${state}`); }}><option>待检查</option><option>正常</option><option>异常</option></select></div>{syncAt && <p className="prototype-inline-status" role="status">{syncAt} 已同步到 {currentTask.id}</p>}</SectionCard><SectionCard title="现场事件时间线" eyebrow="EVIDENCE TIMELINE" action={<Button variant="ghost" onClick={() => downloadText("现场事件时间线.csv", csvText([["时间", "事件", "状态"], ...events.map(item => [item.time, item.title, item.status])]), "text/csv;charset=utf-8")}>导出时间线</Button>}><div className="event-timeline prototype-event-scroll">{events.map(item => <div key={item.id}><time>{item.time}</time><i /><span><strong>{item.title}</strong><small>{item.status}</small></span></div>)}</div></SectionCard></div>
    <SectionCard title="现场隐患记录" eyebrow="FIELD RECORDS" action={<Button variant="secondary" icon={Download} onClick={exportRecords}>导出记录</Button>}><Toolbar><label className="search-field"><Search size={16} /><input value={query} onChange={event => setQuery(event.target.value)} placeholder="搜索隐患描述、编号或来源设备" /></label><select aria-label="现场记录状态" value={recordStatus} onChange={event => setRecordStatus(event.target.value)}>{["全部状态", "待派发", "待整改", "整改中", "待复查", "已整改"].map(item => <option key={item}>{item}</option>)}</select><span className="prototype-muted">共 {filteredRecords.length} 条 · 与项目筛选联动</span><Button variant="ghost" onClick={() => { setQuery(""); setRecordStatus("全部状态"); }}>重置</Button></Toolbar><div className="table-wrap"><table className="data-table prototype-record-table"><colgroup>{[180, 235, 100, 105, 145, 255].map((width, index) => <col key={index} style={{ width }} />)}</colgroup><thead><tr>{["隐患编号", "隐患描述", "风险等级", "当前状态", "发现时间", "操作"].map(head => <th key={head}>{head}</th>)}</tr></thead><tbody>{filteredRecords.map(row => <tr key={row.id}><td title={row.id}>{row.id}<small>{row.source}</small></td><td title={row.title}>{row.title}<small>{row.orderId ? `整改单 ${row.orderId}` : "整改单待生成"}</small></td><td><Pill tone={riskTone(row.risk)}>{row.risk}</Pill></td><td><Pill tone={toneFor(row.status)}>{row.status}</Pill></td><td>{row.foundTime.split(" ")[0]}<small>{row.foundTime.split(" ")[1]}</small></td><td><div className="prototype-table-actions"><Button variant="ghost" onClick={() => { setRecordId(row.id); setActiveKey(row.key); setActiveChecklist(row.checklist); }}>查看详情</Button><Button variant="ghost" onClick={() => openOrder(row, "order")}>{row.orderId ? "查看整改单" : "生成整改单"}</Button>{["待派发", "待整改"].includes(row.status) && <Button variant="ghost" onClick={() => openOrder(row, "dispatch")}>{row.status === "待整改" ? "开始整改" : "派发整改"}</Button>}</div></td></tr>)}{!filteredRecords.length && <tr><td colSpan={6} className="prototype-empty">暂无匹配记录，可截图取证或调整筛选条件。</td></tr>}</tbody></table></div></SectionCard>
    <SectionCard title="录像片段与截图证据" eyebrow="LOCAL EVIDENCE" action={<Button variant="ghost" onClick={() => setPreview({ title: "现场视频示例片段", src: sceneVideos.helmetLive, type: "video", note: "本地图片轮播示例，可在预览中播放或下载。" })}>查看示例片段</Button>}><div className="prototype-evidence-gallery">{records.filter(row => row.id.startsWith("SHOT")).slice(0, 6).map(row => <button key={row.id} onClick={() => setPreview({ title: row.title, src: row.image, type: "image", note: `${row.foundTime} · ${row.source} · 演示取证` })}><img src={row.image} alt={row.title} /><span>{row.title}<small>{row.foundTime}</small></span></button>)}{clips.slice(0, 4).map(clip => <button key={clip.id} onClick={() => setPreview({ title: clip.title, src: clip.src, type: "video", note: `${clip.createdAt} · 本地图片轮播示例，并非实际录像。` })}><span className="prototype-clip-icon"><Play size={25} /></span><span>{clip.title}<small>{clip.createdAt}</small></span></button>)}{!records.some(row => row.id.startsWith("SHOT")) && !clips.length && <p className="prototype-muted">点击“截图取证”、保存补拍截图或停止录制后，证据会展示在这里。</p>}</div></SectionCard>
    <Modal title="现场隐患证据" open={Boolean(selectedClue)} onClose={() => setSelectedClue(null)} wide>{selectedClue && <><div className="evidence-detail"><img src={selectedClue.image} alt={selectedClue.title} /><div><Pill tone={riskTone(selectedClue.risk)}>{selectedClue.risk} · 示例置信度 {selectedClue.confidence}</Pill><h3>{selectedClue.title}</h3><p>{selectedClue.description}</p><div className="detail-grid"><span>发现时间</span><strong>{selectedClue.time}</strong><span>来源设备</span><strong>{channel}</strong><span>关联检查项</span><strong>{selectedClue.checklist}</strong><span>建议动作</span><strong>{selectedClue.measure}</strong></div></div></div><div className="modal-foot"><Button variant="secondary" onClick={() => setSelectedClue(null)}>稍后处理</Button><Button onClick={() => registerClue(selectedClue)}>生成隐患并登记</Button></div></>}</Modal>
    <Modal title={orderMode === "dispatch" ? "派发现场整改" : orderMode === "order" ? "现场整改单" : "现场隐患详情"} open={Boolean(activeRecord)} onClose={() => { setRecordId(null); setOrderMode(null); }} wide>{activeRecord && <>{!orderMode ? <><div className="evidence-detail"><img src={activeRecord.image} alt={activeRecord.title} /><div className="detail-grid">{[["隐患编号", activeRecord.id], ["隐患描述", activeRecord.title], ["风险等级", activeRecord.risk], ["当前状态", activeRecord.status], ["发现时间", activeRecord.foundTime], ["来源设备", activeRecord.source], ["所属项目", activeRecord.project], ["关联检查项", activeRecord.checklist], ["整改措施", activeRecord.measure], ["整改单", activeRecord.orderId || "未生成"]].map(([label, value]) => <React.Fragment key={label}><span>{label}</span><strong>{value}</strong></React.Fragment>)}</div></div><div className="modal-foot"><Button variant="secondary" onClick={() => setRecordId(null)}>关闭</Button><Button variant="secondary" onClick={() => openOrder(activeRecord, "order")}>{activeRecord.orderId ? "查看整改单" : "生成整改单"}</Button>{["待派发", "待整改"].includes(activeRecord.status) && <Button onClick={() => openOrder(activeRecord, "dispatch")}>{activeRecord.status === "待整改" ? "开始整改" : "派发整改"}</Button>}</div></> : <><div className="prototype-note"><Pill tone={riskTone(activeRecord.risk)}>{activeRecord.risk}</Pill><p>{activeRecord.title} · {activeRecord.project}</p><small>{activeRecord.orderId || "保存后生成整改单编号"} · {activeRecord.id}</small></div><div className="form-grid"><Field label="整改责任人"><select value={orderForm.assignee} onChange={event => setOrderForm(value => ({ ...value, assignee: event.target.value }))}>{["李四", "张三", "王五", "赵六", "孙七"].map(item => <option key={item}>{item}</option>)}</select></Field><Field label="整改期限"><input type="date" value={orderForm.deadline} onInput={event => { const deadline = event.currentTarget.value; setOrderForm(value => ({ ...value, deadline })); }} onChange={event => setOrderForm(value => ({ ...value, deadline: event.target.value }))} /></Field><Field label="整改措施" wide><textarea value={orderForm.measure} onChange={event => setOrderForm(value => ({ ...value, measure: event.target.value }))} /></Field></div><p className="prototype-muted">{orderMode === "dispatch" ? `确认后状态变为“${activeRecord.status === "待整改" ? "整改中" : "待整改"}”。` : "整改单保留隐患、来源证据、责任人、期限和建议措施。"}仅保存本地演示记录。</p>{formError && <p className="prototype-form-error" role="alert">{formError}</p>}<div className="modal-foot"><Button variant="secondary" onClick={() => setOrderMode(null)}>返回详情</Button>{activeRecord.orderId && <Button variant="secondary" icon={Download} onClick={() => downloadText(`${activeRecord.orderId}-整改建议书.txt`, `整改建议书（演示）\n编号：${activeRecord.orderId}\n隐患：${activeRecord.title}\n项目：${activeRecord.project}\n来源：${activeRecord.source}\n责任人：${activeRecord.assignee}\n整改期限：${activeRecord.deadline}\n整改措施：${activeRecord.measure}\n状态：${activeRecord.status}`)}>导出整改单</Button>}<Button onClick={saveOrder}>{orderMode === "dispatch" ? "确认派发" : activeRecord.orderId ? "保存整改单" : "生成整改单"}</Button></div></>}</>}</Modal>
    <Modal title="复核指令" open={reviewOpen} onClose={() => setReviewOpen(false)}><div className="form-grid"><Field label="复核专家" wide><select value={reviewTarget} onChange={event => setReviewTarget(event.target.value)}><option>王工 · 电气专家</option><option>赵工 · 消防安全专家</option><option>孙工 · 注册安全工程师</option></select></Field><Field label="关联线索" wide><input readOnly value={activeClue.title} /></Field><Field label="复核说明" wide><textarea value={reviewNote} onChange={event => setReviewNote(event.target.value)} /></Field></div><p className="prototype-muted">指令将记入本地现场时间线，不向人员发送真实消息。</p><div className="modal-foot"><Button variant="secondary" onClick={() => setReviewOpen(false)}>取消</Button><Button onClick={() => { if (!reviewNote.trim()) { notify("请填写复核说明"); return; } addEvent(`复核指令 → ${reviewTarget}：${reviewNote.trim()}`, "待复核"); setReviewOpen(false); notify("复核指令已保存至本地时间线"); }}>保存复核指令</Button></div></Modal>
    <Modal title="SOS 紧急求助" open={sosOpen} onClose={() => setSosOpen(false)}><div className="sos-card"><AlertCircle size={24} /><div><strong>将记录现场位置和当前画面</strong><p>{channel} · {currentHelmet.project}</p><p>演示接收方：运营工作台、远程专家、项目安全负责人。本操作只新增本地求助记录。</p></div></div><div className="modal-foot"><Button variant="secondary" onClick={() => setSosOpen(false)}>取消</Button><Button onClick={() => { addEvent(`SOS 求助：${channel}，${currentHelmet.project}，已关联当前画面`, "待响应"); capture(frame, "SOS 求助现场证据"); setSosOpen(false); notify("紧急求助演示记录已保存"); }}>确认记录求助</Button></div></Modal>
    <Modal title="现场终端设置" open={settingsOpen} onClose={() => setSettingsOpen(false)}><div className="form-grid"><Field label="画面清晰度"><select value={hdMode ? "1080P" : "720P"} onChange={event => setHdMode(event.target.value === "1080P")}><option>1080P</option><option>720P</option></select></Field><Field label="补光灯"><select value={lightOn ? "开启" : "关闭"} onChange={event => setLightOn(event.target.value === "开启")}><option>开启</option><option>关闭</option></select></Field><Field label="画面模式"><select value={infrared ? "红外测温" : "普通画面"} onChange={event => setInfrared(event.target.value === "红外测温")}><option>普通画面</option><option>红外测温</option></select></Field></div><p className="prototype-muted">设置即时应用到当前演示画面。</p><div className="modal-foot"><Button onClick={() => setSettingsOpen(false)}>完成</Button></div></Modal>
    <Modal title="本地演示识别结果" open={analysisOpen} onClose={() => setAnalysisOpen(false)} wide><p className="prototype-note">{analysisAt} · 使用预置示例线索演示识别结果，未请求模型或设备接口。建议结合现场取证和专家复核确认。</p><div className="prototype-analysis-list">{fieldClues.map(clue => <button key={clue.key} onClick={() => { focusClue(clue); setAnalysisOpen(false); setSelectedClue(clue); }}><img src={clue.image} alt={clue.title} /><span>{clue.title}<small>示例置信度 {clue.confidence} · {clue.checklist}</small></span><Pill tone={riskTone(clue.risk)}>{clue.risk}</Pill><ChevronRight size={15} /></button>)}</div><div className="modal-foot"><Button variant="secondary" onClick={() => setAnalysisOpen(false)}>关闭</Button><Button onClick={() => { downloadText("本地演示识别结果.json", JSON.stringify({ demo: true, captureTime: analysisAt, device: channel, detections: fieldClues }, null, 2), "application/json;charset=utf-8"); }}>导出识别结果</Button></div></Modal>
    <Modal title={preview?.title || "现场证据预览"} open={Boolean(preview)} onClose={() => setPreview(null)} wide>{preview && <><div className="prototype-media-preview">{preview.type === "image" ? <img src={preview.src} alt={preview.title} /> : <video src={preview.src} controls preload="metadata" />}</div><p className="prototype-note">{preview.note}</p><div className="modal-foot"><Button variant="secondary" onClick={() => setPreview(null)}>关闭</Button><Button icon={Download} onClick={() => downloadAsset(preview.src, `${preview.title}.${preview.type === "image" ? "jpg" : "webm"}`)}>下载{preview.type === "image" ? "图片" : "片段"}</Button></div></>}</Modal>
  </div>;
}

